package com.pridesys.ticketing.user.service.impl; import com.pridesys.ticketing.dto.*;import com.pridesys.ticketing.entity.*;import com.pridesys.ticketing.repository.UserRepository;import com.pridesys.ticketing.user.service.IUserService;import org.springframework.data.domain.Page;import org.springframework.data.domain.PageRequest;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import java.util.*;
@Service public class UserServiceImpl implements IUserService {private final UserRepository users;private final PasswordEncoder encoder;public UserServiceImpl(UserRepository u,PasswordEncoder e){users=u;encoder=e;}public PageResponse<AuthDtos.ProfileResponse> list(UserEntity a,String q,int page,int size){admin(a);int limit=Math.min(Math.max(1,size),100);Page<UserEntity> result=a.getRole()==UserRole.APP_ADMIN?users.search(q,PageRequest.of(Math.max(0,page),limit)):users.searchByClient(a.getClientId(),q,PageRequest.of(Math.max(0,page),limit));return PageResponse.of(result.map(this::profile));}public AuthDtos.ProfileResponse create(UserEntity a,CreateUser r){admin(a);if(a.getRole()==UserRole.CLIENT_ADMIN&&r.role()==UserRole.APP_ADMIN)throw new AccessDeniedException("Insufficient role");Long client=r.clientId();if(a.getRole()!=UserRole.APP_ADMIN){client=a.getClientId();if(r.clientId()!=null&&!r.clientId().equals(client))throw new AccessDeniedException("Outside client scope");}return profile(users.save(new UserEntity(r.email().trim().toLowerCase(),encoder.encode("Password123!"),r.role(),r.name().trim(),client)));}public void deactivate(UserEntity a,long id){admin(a);var u=target(a,id);u.setActive(false);users.save(u);}public AuthDtos.ProfileResponse update(UserEntity a,long id,UsersProjectsDtos.UpdateUserRequest r){admin(a);var u=target(a,id);u.setName(r.name().trim());u.setMobile(r.mobile());u.setDesignation(r.designation());u.setOffice(r.office());if(r.active()!=null)u.setActive(r.active());return profile(users.save(u));}private boolean visible(UserEntity a,UserEntity u){return a.getRole()==UserRole.APP_ADMIN||Objects.equals(a.getClientId(),u.getClientId());}private UserEntity target(UserEntity a,long id){var u=users.findById(id).orElseThrow();if(!visible(a,u)||a.getRole()==UserRole.CLIENT_ADMIN&&u.getRole()==UserRole.APP_ADMIN)throw new AccessDeniedException("Outside client scope");return u;}private void admin(UserEntity a){if(a.getRole()==UserRole.CLIENT_USER)throw new AccessDeniedException("Insufficient role");}private AuthDtos.ProfileResponse profile(UserEntity u){return new AuthDtos.ProfileResponse(u.getId(),u.getEmail(),u.getRole().name(),u.getName(),u.getMobile(),u.getDesignation(),u.getOffice(),u.isActive());}public record CreateUser(String email,String name,UserRole role,Long clientId){} }
